const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // A point representing Obolon, a district in Kyiv, Ukraine.
  const obolon = ee.Geometry.Point([30.51, 50.51]).buffer(1000); // 1km buffer

  // Date ranges for comparison
  const date_mar_2022 = ee.DateRange('2022-03-01', '2022-03-31');
  const date_may_2022 = ee.DateRange('2022-05-01', '2022-05-31');

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .select('avg_rad');

  const collection_mar = collection.filterDate(date_mar_2022);
  const collection_may = collection.filterDate(date_may_2022);

  const mar_size = collection_mar.size().getInfo();
  const may_size = collection_may.size().getInfo();

  if (mar_size === 0 || may_size === 0) {
    console.log(`Image count March 2022: ${mar_size}`);
    console.log(`Image count May 2022: ${may_size}`);
    console.log("Evidence: No monthly composite found for one or both periods.");
    console.log("C1");
    return;
  }

  const image_mar = collection_mar.first();
  const image_may = collection_may.first();

  // 3. Processing & Calculation
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats_mar = image_mar.reduceRegion({
    reducer: reducer,
    geometry: obolon,
    scale: 500, // VIIRS native resolution is ~500m
    maxPixels: 1e9
  }).getInfo();

  const stats_may = image_may.reduceRegion({
    reducer: reducer,
    geometry: obolon,
    scale: 500,
    maxPixels: 1e9
  }).getInfo();

  const mar_val = stats_mar['avg_rad_mean'];
  const mar_pixels = stats_mar['avg_rad_count'];

  const may_val = stats_may['avg_rad_mean'];
  const may_pixels = stats_may['avg_rad_count'];

  // 4. Validation & Final Answer
  if (mar_pixels === 0 || may_pixels === 0) {
    console.log(`Valid pixels in March 2022: ${mar_pixels}`);
    console.log(`Valid pixels in May 2022: ${may_pixels}`);
    console.log("Evidence: No valid pixels found within the geometry for analysis.");
    console.log("C2");
    return;
  }

  if (mar_val === null || may_val === null || typeof mar_val === 'undefined' || typeof may_val === 'undefined') {
    console.log(`March 2022 radiance: ${mar_val}`);
    console.log(`May 2022 radiance: ${may_val}`);
    console.log("Evidence: Calculation resulted in a null value.");
    console.log("C3");
    return;
  }

  console.log(`March 2022 Avg Radiance: ${mar_val.toFixed(2)} (Pixels: ${mar_pixels})`);
  console.log(`May 2022 Avg Radiance: ${may_val.toFixed(2)} (Pixels: ${may_pixels})`);

  if (may_val < mar_val) {
    console.log("Evidence: Average radiance in May 2022 was lower than in March 2022.");
    console.log("A");
  } else {
    console.log("Evidence: Average radiance in May 2022 was not lower than in March 2022.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred during execution.");
    console.error(err);
    console.log("D");
});
